import json
import sys

def inspect_network():
    try:
        with open('network.json', 'r') as f:
            data = json.load(f)

        print(f"Keys: {data.keys()}")

        if 'column_info' in data:
            print(f"Column Info: {json.dumps(data['column_info'], indent=2)}")

        if 'reserve_requirement' in data:
             print(f"Reserve Requirement: {data['reserve_requirement']}")

        if 'branch' in data:
            print(f"Number of branches: {len(data['branch'])}")
            # Find branch 64-1501
            found = False
            for i, branch in enumerate(data['branch']):
                f_bus = int(branch[0])
                t_bus = int(branch[1])
                if (f_bus == 64 and t_bus == 1501) or (f_bus == 1501 and t_bus == 64):
                    print(f"Found branch at index {i}: From {f_bus} To {t_bus}, RateA (Capacity): {branch[5]}")
                    found = True
                    break
            if not found:
                print("Branch 64-1501 not found.")
        else:
            print("No 'branch' key found.")

        if 'gen' in data:
            print(f"Number of generators: {len(data['gen'])}")

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    inspect_network()

